"""Histograms, bins and membership."""

from typing import List, Tuple

import numpy as np

from arrays.loading import as_array


def histogram(values, bins: int = 5) -> Tuple[List[int], List[float]]:
    counts, edges = np.histogram(as_array(values), bins=bins)
    return counts.tolist(), edges.tolist()


def bin_labels(values, edges) -> np.ndarray:
    """Which bin each value falls in: 0 below the first edge, len(edges) at or past the last."""
    return np.digitize(as_array(values), as_array(edges))


def mask_members(values, allowed) -> np.ndarray:
    """A boolean mask: which values are among ``allowed``."""
    return np.isin(as_array(values), as_array(allowed))


def count_in_bins(values, edges) -> List[int]:
    labels = bin_labels(values, edges)
    return [int(np.sum(labels == label)) for label in range(len(as_array(edges)) + 1)]


def quantiles(values, qs=(0.25, 0.5, 0.75)) -> List[float]:
    return np.quantile(as_array(values), list(qs), method="linear").tolist()

"""Arrays as text."""

from typing import List, Optional, Sequence

import numpy as np

from arrays.errors import ArrayError
from arrays.loading import as_array


def to_csv_lines(matrix, header: Optional[Sequence[str]] = None, places: int = 3) -> List[str]:
    """One CSV line per row, numbers rounded to ``places``; an optional header first."""
    data = np.round(as_array(matrix), places)
    if data.ndim == 1:
        data = data.reshape(1, -1)
    if data.ndim != 2:
        raise ArrayError("only 1-D or 2-D data can be written")
    lines = [",".join(header)] if header else []
    lines += [",".join(f"{value:g}" for value in row) for row in data]
    return lines


def labels_array(labels: Sequence) -> np.ndarray:
    """``labels`` as an array of text."""
    return np.array([str(label) for label in labels], dtype=np.str_)


def is_text(array: np.ndarray) -> bool:
    return array.dtype.type in (np.bytes_, np.str_)


def to_bytes_rows(matrix, places: int = 3) -> List[bytes]:
    return [line.encode("ascii") for line in to_csv_lines(matrix, places=places)]

"""Plane geometry on point arrays."""

from typing import Tuple

import numpy as np

from arrays.errors import ArrayError
from arrays.loading import as_array


def turn_direction(p, q, r) -> int:
    """1 for a left (counter-clockwise) turn p -> q -> r, -1 for a right turn, 0 for a straight line."""
    first = as_array(q) - as_array(p)
    second = as_array(r) - as_array(q)
    cross = first[0] * second[1] - first[1] * second[0]
    return int(np.sign(cross))


def polygon_area(points) -> float:
    """The area of a simple polygon given by its vertices in order (the shoelace formula)."""
    pts = as_array(points)
    if pts.ndim != 2 or pts.shape[1] != 2 or pts.shape[0] < 3:
        raise ArrayError("a polygon needs at least three 2-D points")
    x, y = pts[:, 0], pts[:, 1]
    return float(abs(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1))) / 2)


def reduce_axis(matrix, axis: int, reducer=np.sum) -> np.ndarray:
    """``reducer`` along ``axis``; an ArrayError names an axis the data does not have."""
    data = as_array(matrix)
    try:
        return reducer(data, axis=axis)
    except np.exceptions.AxisError as error:
        raise ArrayError(f"axis {axis} is out of bounds for {data.ndim}-D data") from error


def bounding_box(points) -> Tuple[np.ndarray, np.ndarray]:
    pts = as_array(points)
    return pts.min(axis=0), pts.max(axis=0)


def centroid(points) -> np.ndarray:
    return as_array(points).mean(axis=0)

"""Getting data into arrays."""

from typing import Sequence

import numpy as np

from arrays.errors import ArrayError


def as_array(values) -> np.ndarray:
    """A float64 array of ``values`` (a list, a tuple or an array); an array is used as it is."""
    return np.asarray(values, dtype=np.float64)


def from_records(rows: Sequence[dict], fields: Sequence[str]) -> np.ndarray:
    """A 2-D float array with one row per record and the columns in ``fields`` order."""
    if not rows:
        raise ArrayError("no records")
    try:
        return np.asarray([[row[field] for field in fields] for row in rows], dtype=np.float64)
    except KeyError as error:
        raise ArrayError(f"record lacks the field {error.args[0]!r}") from None


def parse_matrix(text: str) -> np.ndarray:
    """Rows of whitespace-separated numbers, one per line."""
    rows = [[float(cell) for cell in line.split()] for line in text.strip().splitlines() if line.strip()]
    if not rows:
        raise ArrayError("no rows")
    if len({len(row) for row in rows}) != 1:
        raise ArrayError("ragged rows")
    return np.array(rows, dtype=np.float64)


def column(matrix: np.ndarray, index: int) -> np.ndarray:
    """One column of a 2-D array, as its own contiguous array."""
    if matrix.ndim != 2:
        raise ArrayError("a column needs a 2-D array")
    return np.ascontiguousarray(matrix[:, index])

"""Smoothing, integration and simple transforms of 1-D data."""

import numpy as np

from arrays.errors import ArrayError
from arrays.loading import as_array


def moving_average(values, window: int) -> np.ndarray:
    data = as_array(values)
    if window < 1 or window > data.size:
        raise ArrayError("window must be between 1 and the number of values")
    return np.convolve(data, np.ones(window) / window, mode="valid")


def area_under(x, y) -> float:
    """The area under the curve ``y(x)`` by the trapezoid rule."""
    return float(np.trapezoid(as_array(y), as_array(x)))


def stack_rows(rows) -> np.ndarray:
    """Equal-length 1-D sequences as the rows of a 2-D array."""
    arrays = [as_array(row) for row in rows]
    if not arrays or len({array.size for array in arrays}) != 1:
        raise ArrayError("rows must be non-empty and of one length")
    return np.vstack(arrays)


def detrend(values) -> np.ndarray:
    """The values minus their least-squares line."""
    data = as_array(values)
    x = np.arange(data.size, dtype=float)
    slope, intercept = np.polyfit(x, data, 1)
    return data - (slope * x + intercept)


def rescale(values, low: float = 0.0, high: float = 1.0) -> np.ndarray:
    """Min-max scaling into ``[low, high]``; constant data maps to ``low``."""
    data = as_array(values)
    span = data.max() - data.min()
    if span == 0:
        return np.full_like(data, low)
    return low + (data - data.min()) / span * (high - low)

"""Descriptive statistics."""

import numpy as np

from arrays.errors import ArrayError
from arrays.loading import as_array


def describe(values) -> dict:
    data = as_array(values)
    if data.size == 0:
        raise ArrayError("nothing to describe")
    return {
        "count": int(data.size),
        "mean": float(data.mean()),
        "std": float(data.std()),
        "min": float(data.min()),
        "max": float(data.max()),
        "product": float(np.prod(data)),
        "all_positive": bool(np.all(data > 0)),
    }


def zscore(values) -> np.ndarray:
    data = as_array(values)
    spread = data.std()
    if spread == 0:
        return np.zeros_like(data)
    return (data - data.mean()) / spread


def summary_text(values) -> str:
    """``n=3 mean=2.0 std=0.816 range=[1.0, 3.0]``: plain numbers, three decimals at most."""
    data = as_array(values)
    mean = float(np.round(data.mean(), 3))
    spread = float(np.round(data.std(), 3))
    return f"n={data.size} mean={mean!r} std={spread!r} range=[{float(data.min())!r}, {float(data.max())!r}]"


def fill_missing(values, fill=np.nan) -> np.ndarray:
    """A copy with every NaN replaced by ``fill``."""
    data = as_array(values).copy()
    data[np.isnan(data)] = fill
    return data


def running_product(values) -> np.ndarray:
    return np.cumprod(as_array(values))


def has_missing(values) -> bool:
    return bool(np.any(np.isnan(as_array(values))))
